	@Test
	void theDimensionsOfOneCellShareOneKeyGroupAndOnlyEstimatesCarryValues(@TempDir Path directory)
			throws Exception {
		LmdbOperatorFeedbackStats feedback = feedback(directory);
		LogicalLearningKey logical = logical("grouped");
		FrontierCostDimension[] dimensions = { FrontierCostDimension.SOURCE_ROWS_SCANNED,
				FrontierCostDimension.INDEX_SEEKS, FrontierCostDimension.ITERATOR_OPENS,
				FrontierCostDimension.EXPRESSION_EVALUATIONS, FrontierCostDimension.HASH_BUILD_ROWS,
				FrontierCostDimension.HASH_PROBE_ROWS, FrontierCostDimension.PATH_EXPANSIONS,
				FrontierCostDimension.RESULT_ROWS, FrontierCostDimension.REMOTE_CALLS };

		LmdbPlanningReadLog.Log one = record(() -> physical(feedback, logical, dimensions, 1, false));
		LmdbPlanningReadLog.Log nine = record(() -> physical(feedback, logical, dimensions, 9, false));
		LmdbPlanningReadLog.Log nineWithOneEstimate = record(() -> physical(feedback, logical, dimensions, 9, true));
		LmdbPlanningReadLog.Log twoCells = record(() -> {
			physical(feedback, logical, dimensions, 9, false);
			physical(feedback, logical("other-cell"), dimensions, 9, false);
		});

		assertAll(
				() -> assertEquals(1, one.groupCount()),
				() -> assertEquals(1, nine.groupCount(), "nine dimensions of one cell share one key group"),
				() -> assertEquals(9, nine.readCount()),
				() -> assertEquals(2, twoCells.groupCount()),
				() -> assertEquals(8L * LmdbPlanningReadLog.READ_BYTES, nine.retainedBytes() - one.retainedBytes(),
						"a further dimension of a recorded cell charges only its read"),
				() -> assertEquals(5L * Double.BYTES, nineWithOneEstimate.retainedBytes() - nine.retainedBytes(),
						"only a read that returned an estimate stores its predicted input and its values"),
				() -> assertEquals(nine.retainedBytes() - LmdbPlanningReadLog.LOG_BYTES + 9L
						* LmdbPlanningReadLog.READ_BYTES + LmdbPlanningReadLog.GROUP_BYTES
						+ keyBytes(logical("other-cell")),
						twoCells.retainedBytes() - LmdbPlanningReadLog.LOG_BYTES,
						"a second cell charges its group, its reads and its own logical key; shared keys once"));
	}

	@Test
	void aRepeatedKeyReferenceIsChargedOnce(@TempDir Path directory) throws Exception {
		LmdbOperatorFeedbackStats feedback = feedback(directory);
		LogicalLearningKey logical = logical("charged-once");

		LmdbPlanningReadLog.Log exactOnly = record(
				() -> LmdbPlanningReadLog.exactFact(feedback, logical, APPLICABILITY, Double.NaN));
		LmdbPlanningReadLog.Log exactAndLogical = record(() -> {
			LmdbPlanningReadLog.exactFact(feedback, logical, APPLICABILITY, Double.NaN);
			LmdbPlanningReadLog.model(feedback, LmdbPlanningReadLog.LOGICAL, logical, null, APPLICABILITY,
					FrontierCostDimension.OUTPUT_ROWS, FEATURES, 10.0d, decision(null));
		});

		assertEquals(LmdbPlanningReadLog.GROUP_BYTES + LmdbPlanningReadLog.READ_BYTES + 56L,
				exactAndLogical.retainedBytes() - exactOnly.retainedBytes(),
				"the second group references the same logical key and applicability: it charges its group, its read "
						+ "and only the feature envelope it adds");
	}

	@Test
	void aLogOverTheKeyGroupCapIsDroppedAsIncomplete(@TempDir Path directory) throws Exception {
		LmdbOperatorFeedbackStats feedback = feedback(directory);
		String previous = System.setProperty(LmdbPlanningReadLog.MAX_KEY_GROUPS_PROPERTY, "3");
		try {
			LmdbPlanningReadLog.Log atCap = record(() -> {
				for (int index = 0; index < 3; index++) {
					LmdbPlanningReadLog.exactFact(feedback, logical("cap-" + index), APPLICABILITY, Double.NaN);
				}
			});
			LmdbPlanningReadLog.Log overCap = record(() -> {
				for (int index = 0; index < 4; index++) {
					LmdbPlanningReadLog.exactFact(feedback, logical("cap-" + index), APPLICABILITY, Double.NaN);
				}
			});

			assertAll(
					() -> assertTrue(atCap.complete(), "a log at the cap is kept"),
					() -> assertFalse(overCap.complete(), "a log above the cap is dropped"),
					() -> assertEquals("key-group-cap", overCap.incompleteReason()),
					() -> assertEquals(0, overCap.readCount(), "a dropped log retains no reads"),
					() -> assertEquals(LmdbPlanningReadLog.Verdict.INCOMPLETE,
							overCap.replayAgainstOwners(0.0d, () -> {
							}).verdict()));
		} finally {
			if (previous == null) {
				System.clearProperty(LmdbPlanningReadLog.MAX_KEY_GROUPS_PROPERTY);
			} else {
				System.setProperty(LmdbPlanningReadLog.MAX_KEY_GROUPS_PROPERTY, previous);
			}
		}
	}

	@Test
	void outsideAPlanningScopeNothingIsRecorded(@TempDir Path directory) throws Exception {
		LmdbOperatorFeedbackStats feedback = feedback(directory);
		List<LmdbPlanningReadLog.Log> logs = new ArrayList<>();
		Consumer<LmdbPlanningReadLog.Log> previous = LmdbPlanningReadLog.setCompletedPlanningObserver(logs::add);
		try {
			feedback.logicalDimensionDecision(logical("outside"), APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS,
					FEATURES, 10.0d);
			LmdbPlanningReadLog.markIncomplete("outside");
			assertNull(LmdbPlanningReadLog.slice(LmdbPlanningReadLog.mark()),
					"without a planning scope there is no log to slice");
		} finally {
			LmdbPlanningReadLog.setCompletedPlanningObserver(previous);
		}
		assertTrue(logs.isEmpty());
	}

	@Test
	void innerScopesJoinTheOutermost(@TempDir Path directory) throws Exception {
		LmdbOperatorFeedbackStats feedback = feedback(directory);
		LmdbPlanningReadLog.Log log = record(() -> {
			LmdbPlanningReadLog.exactFact(feedback, logical("outer"), APPLICABILITY, Double.NaN);
			LmdbPlanningReadLog.beginPlanning();
			try {
				LmdbPlanningReadLog.exactFact(feedback, logical("inner"), APPLICABILITY, Double.NaN);
			} finally {
				LmdbPlanningReadLog.endPlanning();
			}
			LmdbPlanningReadLog.exactFact(feedback, logical("after-inner"), APPLICABILITY, Double.NaN);
		});

		assertEquals(3, log.readCount(), "an inner scope neither ends the log nor starts another one");
	}

	@Test
	void aSliceSplicedIntoAnotherPlanningDecodesToTheSameReads(@TempDir Path directory) throws Exception {
		LmdbOperatorFeedbackStats feedback = feedback(directory);
		LmdbFilterSelectivityStats filters = filters(directory);
		LmdbPlanningReadLog.Log[] slice = new LmdbPlanningReadLog.Log[1];
		LmdbPlanningReadLog.Log first = record(() -> {
			LmdbPlanningReadLog.exactFact(feedback, logical("before-slice"), APPLICABILITY, Double.NaN);
			LmdbPlanningReadLog.legacy(feedback, 7L);
			LmdbPlanningReadLog.Mark mark = LmdbPlanningReadLog.mark();
			LmdbPlanningReadLog.legacy(feedback, 7L);
			LmdbPlanningReadLog.filterRatio(filters, LmdbPlanningReadLog.FILTER_RATIO, PATTERN, "f", 0.5d);
			LmdbPlanningReadLog.legacy(feedback, 7L);
			slice[0] = LmdbPlanningReadLog.slice(mark);
		});
		LmdbPlanningReadLog.Log second = record(() -> {
			LmdbPlanningReadLog.legacy(feedback, 7L);
			LmdbPlanningReadLog.splice(slice[0]);
		});
		LmdbPlanningReadLog.Log unrecorded = record(() -> LmdbPlanningReadLog.splice(null));

		assertAll(
				() -> assertEquals(4, first.readCount(), "a guard already recorded in this planning is not repeated"),
				() -> assertEquals(2, slice[0].readCount(), "the slice re-records the guard its reads depend on"),
				() -> assertEquals(slice[0].reads(), second.reads().subList(1, 3)),
				() -> assertTrue(second.complete()),
				() -> assertFalse(unrecorded.complete(), "splicing a computation that recorded nothing is unsound"));
	}

	private static void physical(LmdbOperatorFeedbackStats feedback, LogicalLearningKey logical,
			FrontierCostDimension[] dimensions, int count, boolean firstHasEstimate) {
		for (int index = 0; index < count; index++) {
			FrontierLearningModel.DimensionEstimate estimate = index == 0 && firstHasEstimate
					? new FrontierLearningModel.DimensionEstimate(2.0d, 1.0d, 4.0d, 0.1d, 0.01d, 0.02d, 9.0d, 3L,
							0L, 0L)
					: null;
			LmdbPlanningReadLog.model(feedback, LmdbPlanningReadLog.PHYSICAL, logical, PHYSICAL, APPLICABILITY,
					dimensions[index], FEATURES, 1.0d + index, decision(estimate));
		}
	}

	private static long keyBytes(LogicalLearningKey key) {
		return LmdbPlanningReadLog.logicalKeyBytes(key);
	}

	private static FrontierLearningModel.DimensionDecision decision(FrontierLearningModel.DimensionEstimate estimate) {
		return new FrontierLearningModel.DimensionDecision(new LearningGateDecision(
				estimate == null ? LearningGateDecision.Outcome.INSUFFICIENT_SUPPORT
						: LearningGateDecision.Outcome.APPLICABLE,
				0L, 0L, Double.NaN, Double.NaN), estimate);
	}

	private static void assertRead(LmdbPlanningReadLog.Read read, byte kind, Object first, Object second,
			Object third, Object fourth, int dimension, double[] values, long[] counts) {
		assertAll(
				() -> assertEquals(kind, read.kind(), "kind"),
				() -> assertSame(first, read.first(), "first key reference"),
				() -> assertSame(second, read.second(), "second key reference"),
				() -> assertSame(third, read.third(), "third key reference"),
				() -> assertSame(fourth, read.fourth(), "fourth key reference"),
				() -> assertEquals(dimension, read.dimension(), "dimension"),
				() -> assertArrayEquals(values, read.values(), "values"),
				() -> assertArrayEquals(counts, read.counts(), "counts"));
	}

	static LmdbPlanningReadLog.Log record(Runnable reads) {
		List<LmdbPlanningReadLog.Log> logs = new ArrayList<>();
		Thread owner = Thread.currentThread();
		Consumer<LmdbPlanningReadLog.Log> previous = LmdbPlanningReadLog.setCompletedPlanningObserver(log -> {
			if (Thread.currentThread() == owner) {
				logs.add(log);
			}
		});
		try {
			LmdbPlanningReadLog.beginPlanning();
			try {
				reads.run();
			} finally {
				LmdbPlanningReadLog.endPlanning();
			}
		} finally {
			LmdbPlanningReadLog.setCompletedPlanningObserver(previous);
		}
		assertEquals(1, logs.size(), "one outermost planning scope yields one log");
		return logs.get(0);
	}

	static LogicalLearningKey logical(String name) {
		return LogicalLearningKey.of("statement-pattern", name, "children", "predicates", "s,o", "none",
				"bag|duplicate-sensitive|sparql-unbound", "default");
	}

	private static LmdbOperatorFeedbackStats feedback(Path directory) throws Exception {
		Path estimatorPath = directory.resolve("read-log-encoding.rjes");
		Files.createDirectories(estimatorPath);
		Files.writeString(estimatorPath.resolve("metadata.bin"), "metadata");
		return new LmdbOperatorFeedbackStats(estimatorPath, () -> IDENTITY, () -> true, () -> 0L);
	}

	private static LmdbFilterSelectivityStats filters(Path directory) {
		return new LmdbFilterSelectivityStats(directory.resolve("read-log-encoding-filters.rjes"),
				mock(TripleStore.class), mock(ValueStore.class), false, 0L, 0, false, () -> IDENTITY, 0, () -> true,
				() -> 0L);
	}
